@MainActor func transient_SymbolBezierCurve_objectDisplay (
       _ self_x1 : CanariLength,                           
       _ self_y1 : CanariLength,                           
       _ self_x2 : CanariLength,                           
       _ self_y2 : CanariLength,                           
       _ self_cpx1 : CanariLength,                         
       _ self_cpy1 : CanariLength,                         
       _ self_cpx2 : CanariLength,                         
       _ self_cpy2 : CanariLength,                         
       _ prefs_symbolColor : NSColor,                      
       _ prefs_symbolDrawingWidthMultipliedByTen : Int
) -> EBShape {
//--- START OF USER ZONE 2
  var bp = BezierPath ()
  bp.move (to: NSPoint (x: self_x1, y: self_y1))
  bp.curve (
    to: NSPoint (x: self_x2, y: self_y2),
    controlPoint1: NSPoint (x: self_cpx1, y: self_cpy1),
    controlPoint2: NSPoint (x: self_cpx2, y: self_cpy2)
  )
  bp.lineWidth = CGFloat (prefs_symbolDrawingWidthMultipliedByTen) / 10.0
  bp.lineCapStyle = .round
  var shape = EBShape ()
  shape.add (stroke: [bp], prefs_symbolColor)
  return shape
//--- END OF USER ZONE 2
}

